import React, { useState, useEffect } from 'react';
import { getCards, createCard, updateCard, deleteCard } from '../services/api';

const Column = ({ column, onUpdate, onDelete }) => {
  const [cards, setCards] = useState([]);
  const [newCardContent, setNewCardContent] = useState('');

  useEffect(() => {
    fetchCards();
  }, [column._id]);

  const fetchCards = async () => {
    const data = await getCards(column._id);
    setCards(data);
  };

  const handleCreateCard = async (e) => {
    e.preventDefault();
    if (!newCardContent.trim()) return;

    await createCard(newCardContent, column._id, cards.length);
    setNewCardContent('');
    fetchCards();
  };

  const handleUpdateCard = async (cardId, content) => {
    await updateCard(cardId, content);
    fetchCards();
  };

  const handleDeleteCard = async (cardId) => {
    await deleteCard(cardId);
    fetchCards();
  };

  const handleDragStart = (e, cardId) => {
    e.dataTransfer.setData('cardId', cardId);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = async (e, targetCardId) => {
    e.preventDefault();
    const draggedCardId = e.dataTransfer.getData('cardId');

    if (draggedCardId === targetCardId) return;

    const draggedCard = cards.find(c => c._id === draggedCardId);
    const targetCard = cards.find(c => c._id === targetCardId);

    if (!draggedCard || !targetCard) return;

    const newOrder = targetCard.order;
    await updateCard(draggedCardId, draggedCard.content, newOrder);
    fetchCards();
  };

  return (
    <div className="column">
      <h3>{column.title}</h3>

      <form onSubmit={handleCreateCard}>
        <input
          type="text"
          value={newCardContent}
          onChange={(e) => setNewCardContent(e.target.value)}
          placeholder="New card content"
        />
        <button type="submit">Add Card</button>
      </form>

      <div className="cards">
        {cards.map((card) => (
          <div
            key={card._id}
            className="card"
            draggable
            onDragStart={(e) => handleDragStart(e, card._id)}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, card._id)}
          >
            <input
              type="text"
              value={card.content}
              onChange={(e) => handleUpdateCard(card._id, e.target.value)}
            />
            <button onClick={() => handleDeleteCard(card._id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Column;
